from collections import defaultdict
n=5
N=25
def rc(k): return divmod(k,n)
def adj(a,b):
    ra,ca=rc(a); rb,cb=rc(b)
    return sorted((abs(ra-rb),abs(ca-cb)))==[1,2]
neigh={i:[j for j in range(N) if adj(i,j)] for i in range(N)}
print(neigh)
fixed={0:0,3:23,4:16,5:5,15:15,22:24}
# verify fixed consecutive adjacencies
for i in range(24):
    if i in fixed and i+1 in fixed:
        print(i, fixed[i], fixed[i+1], adj(fixed[i], fixed[i+1]))

# DFS with position fixed constraints, Warnsdorff / forward checking
path=[None]*N
used=[False]*N
for pos,cell in fixed.items():
    path[pos]=cell
    if used[cell]: print('duplicate')
    used[cell]=True

# Need fill sequentially respecting fixed. We can simple backtrack position order 0..24.
# since fixed future used mark is tricky: a fixed cell cannot be used earlier. used includes fixed all, so for variable positions cannot use fixed cells. good.
# At fixed positions, check prev adjacency.

def dfs(pos):
    if pos==N:
        return True
    if path[pos] is not None:
        if pos>0 and not adj(path[pos-1], path[pos]): return False
        return dfs(pos+1)
    prev=path[pos-1]
    # candidates neighbors not used, not fixed (already used fixed true), and if next fixed check adjacency maybe
    cands=[c for c in neigh[prev] if not used[c]]
    # if next is fixed, candidate must adj next
    if pos+1<N and path[pos+1] is not None:
        nxt=path[pos+1]
        cands=[c for c in cands if adj(c,nxt)]
    # order by onward degree considering fixed future?
    def onward(c):
        return sum(1 for d in neigh[c] if not used[d])
    cands.sort(key=onward)
    for c in cands:
        path[pos]=c; used[c]=True
        if dfs(pos+1): return True
        used[c]=False; path[pos]=None
    return False
print('dfs', dfs(1), path)
if path[24] is not None:
    print(path)
    print(len(set(path)), all(adj(path[i], path[i+1]) for i in range(24)))
